    def __init__(self, n: int):
        self.n = 1
        while self.n < n:
            self.n *= 2
        self.tree = [0] * (2 * self.n)
        self.lazy = [0] * (2 * self.n)

    def update(self, k: int, x: int) -> None:
        k += self.n
        self.lazy[k] += x
        while k > 1:
            k //= 2
            self.tree[k] = max(self.tree[2 * k], self.tree[2 * k + 1]) + self.lazy[k]

